/* Wording for trace events.
 *
 * The trace schema carries structured facts and no prose — how a step is
 * phrased is a presentation decision, and keeping it out of the wire format
 * means translation never touches the core.
 *
 * For the canned traces on this page, the sentences are generated by the
 * Python renderer at build time and shipped alongside the trace. This file
 * exists only for traces made *in the browser*, which have no build step to
 * come from. It is therefore the one place wording is duplicated, and
 * tests/test_js_explain.py renders the same events through both this file and
 * src/solitaire_lab/render/explain.py and fails if a single character differs.
 *
 * Mirrors: src/solitaire_lab/render/explain.py */

const HEADLINES = {
  move_joker_a: "Move joker A down one",
  move_joker_b: "Move joker B down two",
  triple_cut: "Triple cut",
  count_cut: "Count cut",
  output: "Read the output card",
};

/** A short title for the step, e.g. "Triple cut". */
export function headline(event) {
  if (HEADLINES[event.phase]) return HEADLINES[event.phase];
  return event.phase
    .split("_")
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase())
    .join(" ");
}

/** A one- or two-sentence account of why the deck changed as it did. */
export function explain(event) {
  const m = event.meta;

  if (event.phase === "move_joker_a" || event.phase === "move_joker_b") {
    const positions = m.positions === 1 ? "one position" : `${m.positions} positions`;
    if (m.wrapped) {
      return (
        `Joker ${m.joker} moves down ${positions}. It ran off the bottom, so it wraps round to ` +
        `just below the top card, skipping the top itself, and ends at position ` +
        `${m.to_index + 1}.`
      );
    }
    return (
      `Joker ${m.joker} moves down ${positions}, from position ` +
      `${m.from_index + 1} to ${m.to_index + 1}.`
    );
  }

  if (event.phase === "triple_cut") {
    const top = m.top_len;
    const bottom = m.bottom_len;
    if (top === 0 && bottom === 0) {
      return "The jokers are already at the very top and bottom, so there is nothing outside them to swap.";
    }
    return (
      `Everything outside the two jokers switches sides: the ${top} card(s) above the first joker ` +
      `and the ${bottom} card(s) below the second trade places. The ${m.middle_len} cards from ` +
      `one joker to the other stay exactly as they were.`
    );
  }

  if (event.phase === "count_cut") {
    const count = m.count;
    if (m.from_letter) {
      const letter = m.letter;
      const source = letter ? `the passphrase letter ${letter} (worth ${count})` : `a count of ${count}`;
      return (
        `An extra count cut driven by ${source}: move that many cards from the top ` +
        `to just above the bottom card.`
      );
    }
    if (m.identity) {
      return (
        `The bottom card is ${m.bottom_card}, a joker, worth 53. Cutting 53 of the ` +
        `54 cards to just above the bottom card puts every one of them straight back, ` +
        `so the deck is unchanged.`
      );
    }
    return (
      `The bottom card is ${m.bottom_card}, worth ${count}. Move ${count} card(s) ` +
      `from the top to just above it. The bottom card itself never moves.`
    );
  }

  if (event.phase === "output") {
    const top = m.top_card;
    const count = m.count;
    const card = m.output_card;
    if (m.is_joker) {
      return (
        `The top card is ${top}, worth ${count}. Counting ${count} down lands on ${card}, a joker. ` +
        `Jokers produce no output, so this round is discarded and we run the whole thing again.`
      );
    }
    return (
      `The top card is ${top}, worth ${count}. Counting ${count} down lands on ${card}. ` +
      `That card's value is this round's keystream number. The deck is not changed by this step.`
    );
  }

  return "";
}

/** Attach a Python-shaped explanations sidecar to a browser-made trace. */
export const withExplanations = (trace) => ({
  ...trace,
  explanations: trace.events.map((e) => ({ headline: headline(e), text: explain(e) })),
});
